// План specs/admin-coupons.md 2.6 (кейс CP-13). Admin, десктоп, EN. @prod-safe: окно Redemptions только открывается.
import { test, expect } from '../../fixtures';
import {
  COUPONS, USER_EMAIL,
  blockCouponWrites, couponRow, expectNoCouponWrites, openCoupons, restoreTest, startInTest,
} from './coupon-helpers';

test('Coupon Redemptions: started checkout is listed as account e-mail + "At checkout" (QA-R1-PCT-1910) #b93722 #a10206 @desktop @prod-safe', async ({ asUser }) => {
  const page = await asUser('admin');
  await startInTest(page);
  const writes = await blockCouponWrites(page);
  try {
    await openCoupons(page);
    // Источник: комментарий программиста п.4 — «Redemptions» показывает, кто и когда погасил; ручная проверка 19.10 (r1-s4-pct-redemptions).
    await couponRow(page, COUPONS.r1pct).getByRole('button', { name: 'Redemptions', exact: true }).click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: `Redemptions of ${COUPONS.r1pct}` })).toBeVisible();
    const entry = dlg.locator('li, tr, div').filter({ hasText: USER_EMAIL }).filter({ hasText: 'At checkout' }).last();
    await expect(entry).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(dlg).toBeHidden();
  } finally {
    await restoreTest(page);
  }
  expectNoCouponWrites(writes);
});
